use bevy::prelude::*;
use forge_engine::{Project,Simulation,project_point};
use std::path::PathBuf;
#[derive(Resource)] struct Game{project:Project,sim:Simulation}
#[derive(Component)] struct ObjectId(uuid::Uuid);
fn main(){let path=std::env::args_os().nth(1).map(PathBuf::from).unwrap_or_else(||PathBuf::from("project.forge.json"));let path=match path.canonicalize(){Ok(p)=>p,Err(e)=>{eprintln!("Project: {e}");return;}};let p=match Project::load(&path){Ok(p)=>p,Err(e)=>{eprintln!("{e}");return;}};let root=path.parent().unwrap().to_string_lossy().into_owned();App::new().insert_resource(Game{project:p.clone(),sim:Simulation::default()}).add_plugins(DefaultPlugins.set(AssetPlugin{file_path:root,..default()}).set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:p.name,..default()}),..default()})).add_systems(Startup,setup).add_systems(Update,tick).run();}
fn setup(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>){commands.spawn(Camera2d);for o in &game.project.objects{if o.camera{continue;}let mut sprite=Sprite::from_color(Color::srgba_u8(o.color[0],o.color[1],o.color[2],o.color[3]),Vec2::from_array(o.size));if let Some(path)=&o.sprite{sprite.image=assets.load(path.clone());}commands.spawn((sprite,Transform::default(),ObjectId(o.id)));}}
fn tick(time:Res<Time>,keys:Res<ButtonInput<KeyCode>>,mut game:ResMut<Game>,images:Res<Assets<Image>>,mut sprites:Query<(&ObjectId,&mut Transform,&mut Sprite),Without<Camera2d>>,mut cameras:Query<&mut Transform,With<Camera2d>>){let d=[(keys.pressed(KeyCode::KeyD) as i32-keys.pressed(KeyCode::KeyA) as i32) as f32,(keys.pressed(KeyCode::KeyW) as i32-keys.pressed(KeyCode::KeyS) as i32) as f32];let g=&mut *game;g.sim.step(&mut g.project,time.delta_secs(),d);for (id,mut t,mut s) in &mut sprites{if let Some(o)=g.project.objects.iter().find(|o|o.id==id.0){let p=forge_engine::sprite_center(o,g.project.isometric);t.translation=Vec3::new(p[0],p[1],o.layer as f32*10.+if g.project.isometric{-p[1]*0.001}else{0.});t.rotation=Quat::from_rotation_z(o.rotation.to_radians());if o.sprite.is_some(){if let Some(img)=images.get(&s.image){let uv=o.animation.uv(g.sim.elapsed);let size=img.size().as_vec2();s.rect=Some(Rect::from_corners(Vec2::from_array(uv[0])*size,Vec2::from_array(uv[2])*size));}}}}if let Some(o)=g.project.objects.iter().find(|o|o.camera){let p=project_point(o.position,g.project.isometric);for mut t in &mut cameras{t.translation.x=p[0];t.translation.y=p[1];}}}
